import { render } from '@solidjs/web';
import { createOptimisticStore, action, until, For, Loading } from 'solid-js';
import { server } from './server';
import './styles.css';

let nextId = 1;

function Chat() {
  const [messages, setMessages] = createOptimisticStore(() => server.watch(), []);

  const send = action(function* (text) {
    const id = `m${nextId++}`;
    setMessages((draft) => {
      draft.push({ id, text, pending: true });
    });
    yield server.send({ id, text });
  });

  return (
    <Loading fallback={<p>Connecting...</p>}>
      <For each={messages}>
        {(message) => <p class={{ pending: !!message.pending }}>{message.text}</p>}
      </For>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          const input = event.currentTarget.elements.text;
          if (input.value.trim()) send(input.value);
          input.value = '';
        }}
      >
        <input name="text" placeholder="Say something" /> <button>Send</button>
      </form>
    </Loading>
  );
}

render(() => <Chat />, document.getElementById('app'));

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// A pretend chat server. Sending returns quickly, but the message only
// shows up in the live feed a second later, once the server has stored it.
let messages = [{ id: 'welcome', text: 'Welcome to the chat!' }];
const listeners = new Set();

export const server = {
  async send(message) {
    await sleep(150);
    setTimeout(() => {
      messages = [...messages, message];
      for (const listener of listeners) listener(messages);
    }, 1000);
  },
  // The live feed: yields the full list now, then again after every change.
  async *watch() {
    yield messages;
    while (true) {
      yield await new Promise((resolve) => {
        const listener = (list) => {
          listeners.delete(listener);
          resolve(list);
        };
        listeners.add(listener);
      });
    }
  },
};

import { render } from '@solidjs/web';
import { createOptimisticStore, action, until, For, Loading } from 'solid-js';
import { server } from './server';
import './styles.css';

let nextId = 1;

function Chat() {
  const [messages, setMessages] = createOptimisticStore(() => server.watch(), []);

  const send = action(function* (text) {
    const id = `m${nextId++}`;
    setMessages((draft) => {
      draft.push({ id, text, pending: true });
    });
    yield server.send({ id, text });
    yield until(() => messages.some((message) => message.id === id));
  });

  return (
    <Loading fallback={<p>Connecting...</p>}>
      <For each={messages}>
        {(message) => <p class={{ pending: !!message.pending }}>{message.text}</p>}
      </For>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          const input = event.currentTarget.elements.text;
          if (input.value.trim()) send(input.value);
          input.value = '';
        }}
      >
        <input name="text" placeholder="Say something" /> <button>Send</button>
      </form>
    </Loading>
  );
}

render(() => <Chat />, document.getElementById('app'));

